define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_54.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e201134","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_55.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e201238","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_52.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e201342","topics":[]},{"title":"Removing the Integrated System Cabinet (ISC) Ethernet switch","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingTheISCEthernetSwitch.html","attributes":{"data-id":"id_2014301"},"menu":{"hasChildren":false},"tocID":"id_2014301-d46e201446","topics":[]},{"title":"Installing the Integrated System Cabinet (ISC) Ethernet switch","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_InstallingTheISCEthernetSwitch.html","attributes":{"data-id":"id_2014302"},"menu":{"hasChildren":false},"tocID":"id_2014302-d46e201549","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_54.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e201652","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_54.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e201756","topics":[]},{"title":"Doing the host datapath diagnostic","shortdesc":"<p class=\"shortdesc\">The host datapath diagnostic makes sure of the Ethernet communication links between the host computer and the processor boards within the Integrated Control Engine (ICE).<\/p>","href":"r_diag_Host-Datapath-Diagnostics_12457984.html","attributes":{"data-id":"id_15666846"},"menu":{"hasChildren":true},"tocID":"id_15666846-d46e201860","next":"id_15666846-d46e201860"},{"title":"Doing the host-Image Compute Node (ICN) Ethernet path diagnostic","shortdesc":"<p class=\"shortdesc\">The host-Image Compute Node (ICN) Ethernet path diagnostic makes sure that network connectivity exists between the host and an ICN.<\/p>","href":"c_Host-ICN-Ethernet-Path_15625812.html","attributes":{"data-id":"id_13106466"},"menu":{"hasChildren":true},"tocID":"id_13106466-d46e202070","next":"id_13106466-d46e202070"},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_81.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e202281","topics":[]}]});